import React, { useEffect, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";

function Dashboard() {
  const [responseData, setResponseData] = useState([]);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);

  const location = useLocation();
  const navigate = useNavigate();

  useEffect(() => {
    const loginPayload = {
      userid: location.state?.userid,
      password: location.state?.password,
    };

    if (!loginPayload.userid || !loginPayload.password) {
      navigate("/"); // redirect to login if no credentials
      return;
    }

    const baseUrl = "https://novaoffice.novasoftwares.com/service.aspx";
    const queryParams = new URLSearchParams({
      ApiVer: "1",
      Devid: "online",
      AppId: "NV01",
      Lat: "0",
      Lng: "0",
      Control: "auth",
      data: JSON.stringify(loginPayload),
    });

    fetch(`${baseUrl}?${queryParams.toString()}`)
      .then((res) => {
        if (!res.ok) throw new Error("Failed to fetch");
        return res.json();
      })
      .then((data) => {
        if (Array.isArray(data) && data[0]?.Result === "error") {
          setError("Invalid user ID or password.");
        } else {
          setResponseData(data);
        }
        setLoading(false);
      })
      .catch((err) => {
        console.error("Fetch error:", err);
        setError("Something went wrong while connecting to the server.");
        setLoading(false);
      });
  }, [location.state, navigate]);

  return (
    <div
      style={{
        padding: "2rem",
        fontFamily: "Arial",
        backgroundColor: "#f4f7fa",
        minHeight: "100vh",
      }}
    >
      <div
        style={{
          background: "white",
          padding: "2rem",
          borderRadius: "12px",
          maxWidth: "700px",
          margin: "0 auto",
          boxShadow: "0 0 10px rgba(0,0,0,0.1)",
        }}
      >
        <h2 style={{ marginBottom: "1rem" }}>Fetched Details</h2>

        {loading ? (
          <p>Loading...</p>
        ) : error ? (
          <div
            style={{
              backgroundColor: "#ffe6e6",
              color: "#cc0000",
              padding: "1rem",
              border: "1px solid #cc0000",
              borderRadius: "8px",
            }}
          >
            <strong>Error:</strong> {error}
          </div>
        ) : (
          responseData.map((item, index) => (
            <div
              key={index}
              style={{
                padding: "1rem",
                border: "1px solid #ddd",
                borderRadius: "8px",
                marginBottom: "1rem",
                backgroundColor: "#f9f9f9",
              }}
            >
              <p>
                <strong>Unit ID:</strong> {item.UnitId}
              </p>
              <p>
                <strong>Unit Name:</strong> {item.UnitName}
              </p>
              <p>
                <strong>User ID:</strong> {item.UserId}
              </p>
              <p>
                <strong>Address:</strong>{" "}
                {Array.isArray(item.Address)
                  ? item.Address.map((line, idx) => <div key={idx}>{line}</div>)
                  : item.Address || "N/A"}
              </p>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

export default Dashboard;
